  "berat": { scores: { beaches: 3, nightlife: 8, food: 9, activities: 8, family: 7, value: 10 }, tags: ["budget", "culture", "unesco"], foodPerDay: "$15–30", hotelPerNight: "$38–114", insiderTip: "There is no shuttle from TIA to Berat — rent a car directly at the airport or pre-book a private transfer. The bus requires two changes via Tirana and takes 3.5 hours total." },
  "bergen": { scores: { beaches: 2, nightlife: 9, food: 8, activities: 9, family: 6, value: 6 }, tags: ["nightlife", "food", "culture"], tagsDerived: true, foodPerDay: "$52–67", hotelPerNight: "$133–171", dishes: ["Fiskesuppe", "Bergensk pinnekjøtt", "Fiskeballer"], sights: ["Bryggen (Hanseatic Wharf)", "Fløyen", "Bergen fish market"], insiderTip: "Take the Fløyen funicular at 08:00 before tourists fill the car and hike down the Fløyen Trail 6 (3 km, 45 minutes) back to the center along a forest path with views. Free descent. Bring coffee in a thermos and enjoy the morning mist over Bergen and the fjords below." },
