  "bordeaux": { scores: { beaches: 2, nightlife: 9, food: 8, activities: 9, family: 6, value: 6 }, tags: ["nightlife", "food", "culture"], tagsDerived: true, foodPerDay: "$33–48", hotelPerNight: "$86–114", dishes: ["Entrecôte à la bordelaise", "Lamproie à la bordelaise", "Canelé"], sights: ["La Cité du Vin", "Place de la Bourse", "Cathedral of Saint-André and Pey-Berland Tower"], insiderTip: "Go to Miroir d'eau on Place de la Bourse at 20:30 at sunset — the water mirror reflects the pink-golden light against the neoclassical facades and children run through the shallow water film. Buy a bottle of Bordeaux Rouge ($7–10 from a wine shop) and enjoy on the quay. One of Europe's most beautiful free experiences." },
