  "chiang-mai": { scores: { beaches: 3, nightlife: 8, food: 9, activities: 8, family: 7, value: 10 }, tags: ["nightlife", "food", "culture"], tagsDerived: true, foodPerDay: "$10–19", hotelPerNight: "$29–52", dishes: ["Khao Soi", "Sai Ua", "Pad Thai"], sights: ["Doi Suthep", "Old City", "Sunday Walking Street"], insiderTip: "Rent a scooter and ride Ring Road around the Old City moat at sunrise (06:00) — almost no tourists, temples open and monks are out collecting alms (tak bat). Free and unforgettable." },
