  "colombo": { scores: { beaches: 7, nightlife: 8, food: 9, activities: 8, family: 7, value: 10 }, tags: ["nightlife", "food", "culture"], tagsDerived: true, foodPerDay: "$14–24", hotelPerNight: "$38–62", dishes: ["Rice and Curry", "Kottu Roti", "Hoppers (Appa)"], sights: ["Temple of the Tooth (Kandy)", "Sigiriya Rock Fortress", "Yala National Park"], insiderTip: "Book the Kandy–Ella train ticket (observation car) directly upon arrival — it's one of the world's most beautiful train journeys through tea plantations and waterfalls. Eat breakfast on the train (pre-ordered from your hotel) and watch Nuwara Eliya's mountain scenery pass by." },
  "comporta": { scores: { beaches: 9, nightlife: 7, food: 8, activities: 6, family: 8, value: 3 }, tags: ["beach", "culture", "luxury"], insiderTip: "Book accommodation for 2+ nights — Comporta reveals its best side beyond day-trippers." },
