  "cordoba-argentina": { scores: { beaches: 1, nightlife: 5, food: 9, activities: 10, family: 7, value: 6 }, tags: ["culture", "history", "student"], foodPerDay: "$24–48", hotelPerNight: "$57–171", insiderTip: "Drive up into Sierras de Córdoba and stay in La Cumbrecita — a Bavarian mountain village without cars where hiking trails meet Alpine pastry shops." },
