  "sydney": { scores: { beaches: 9, nightlife: 7, food: 8, activities: 8, family: 8, value: 4 }, tags: ["city-break", "long-haul"], foodPerDay: "$43–62", hotelPerNight: "$133–181", dishes: ["Meat pie", "Barramundi", "Tim Tam"], sights: ["Sydney Opera House", "Harbour Bridge Climb", "Bondi to Coogee Coastal Walk"], insiderTip: "Take the Manly Ferry at 07:30 from Circular Quay ($8 AUD) and get off at Manly Beach — you've seen the Harbour Bridge and Opera House in morning light from the water, eaten breakfast in quiet Manly, and taken a morning swim in the Pacific, all for $8 AUD." },
