  "tallinn": { scores: { beaches: 1, nightlife: 8, food: 9, activities: 8, family: 7, value: 10 }, tags: ["nightlife", "food", "culture"], tagsDerived: true, foodPerDay: "$24–33", hotelPerNight: "$57–86", dishes: ["Verivorst", "Kiluleib", "Mulgikapsad"], sights: ["Old Town", "Alexander Nevsky Cathedral", "Telliskivi Creative City"], insiderTip: "Climb Toompea Hill via Pikk jalg street (medieval 'long foot') and stand at Patkuli viewpoint at 21:00 on midsummer evening — Tallinn glows in the evening sun with towers against the bright horizon. Then walk down to Katarina Passage with craftspeople and ceramicists — one of Old Town's most beautiful medieval alleyways." },
