  "tivat": { scores: { beaches: 9, nightlife: 7, food: 8, activities: 6, family: 8, value: 3 }, tags: ["beach", "luxury", "nature"], foodPerDay: "$24–38", hotelPerNight: "$67–171", insiderTip: "Drive the narrow mountain road up Kotor Mountain — hairpin turns to 1,700 meters above Kotor Bay, one of Europe's most spectacular views. A 1-hour drive." },
