  "triest": { scores: { beaches: 2, nightlife: 9, food: 8, activities: 9, family: 6, value: 6 }, tags: ["nightlife", "food", "culture"], tagsDerived: true, foodPerDay: "$29–43", hotelPerNight: "$76–114", dishes: ["Jota", "Sardoni in savor", "Caffè triestino"], sights: ["Piazza Unità d'Italia", "Castello di Miramare", "Canal Grande"], insiderTip: "Caffè San Marco was Joyce's workplace — order a 'capo in B' (espresso with foam in a glass) and write like a writer." },
  "trinidad": { scores: { beaches: 3, nightlife: 5, food: 9, activities: 10, family: 7, value: 6 }, tags: ["culture"], foodPerDay: "$24–43", hotelPerNight: "$86–238", insiderTip: "Visit Maracas Beach on a Saturday and eat a local bake-and-shark — Richard's stand has been the institution since the 1980s." },
