  "tromso": { scores: { beaches: 2, nightlife: 9, food: 8, activities: 9, family: 6, value: 6 }, tags: ["nightlife", "food", "culture"], tagsDerived: true, foodPerDay: "$52–67", hotelPerNight: "$133–171", dishes: ["Reindeer", "Torsk (Skrei)", "Brunost"], sights: ["Arctic Cathedral (Ishavskatedralen)", "Fjellheisen cable car", "Polaria Museum"], insiderTip: "Book a table at Bardus Bistro or Emma's Drømmekjøkken for dinner with reindeer and Arctic seafood — then stay out until midnight and look up. Tromsø center has little enough light pollution that faint northern lights are visible above the Arctic Cathedral when the KP index is 3+." },
  "trondheim": { scores: { beaches: 2, nightlife: 9, food: 8, activities: 9, family: 6, value: 6 }, tags: ["nightlife", "food", "culture"], tagsDerived: true, foodPerDay: "$33–57", hotelPerNight: "$95–171", dishes: ["Brown cheese", "Bidos", "Local beer from Dahls and E.C. Dahls"], sights: ["Nidaros Cathedral", "Bakklandet", "Trøndelag Folk Museum Sverresborg"], insiderTip: "Try the Trampe bike lift in Bakklandet — the world's only one — and eat at Kafé Løft for the city's best brunch." },
