  "turin": { scores: { beaches: 2, nightlife: 9, food: 8, activities: 9, family: 6, value: 6 }, tags: ["nightlife", "food", "culture"], tagsDerived: true, foodPerDay: "$33–48", hotelPerNight: "$76–114", dishes: ["Bicerin", "Agnolotti", "Gianduja"], sights: ["Mole Antonelliana", "Palazzo Reale", "Egyptian Museum"], insiderTip: "Start your morning at Caffè Al Bicerin (since 1763) — drink the original Bicerin and see the scales used by Cavour and Nietzsche." },
