  "ulaanbaatar": { scores: { beaches: 2, nightlife: 9, food: 8, activities: 9, family: 6, value: 6 }, tags: ["nightlife", "food", "culture"], tagsDerived: true, foodPerDay: "$19–33", hotelPerNight: "$67–114", dishes: ["Buuz", "Khorkhog", "Airag"], sights: ["Sükhbaatar Square", "Gandan Monastery", "Genghis Khan Statue"], insiderTip: "Book a 3-day jeep tour to Terelj National Park plus ger-camp — Przewalski's horses, shamanism, starry skies without light pollution." },
