  "valldemossa": { scores: { beaches: 3, nightlife: 5, food: 9, activities: 10, family: 7, value: 6 }, tags: ["culture", "mountains"], insiderTip: "Book accommodation for 2+ nights — Valldemossa reveals its best side beyond day-trippers." },
