  "varanasi": { scores: { beaches: 1, nightlife: 2, food: 7, activities: 10, family: 4, value: 9 }, tags: ["city-break", "culture", "spiritual"], foodPerDay: "$10–24", hotelPerNight: "$29–114", dishes: ["Kachori sabzi", "Banarasi paan", "Lassi in clay cups from old lassi shops"], sights: ["Dashashwamedh Ghat", "Dawn boat ride along ghats as pilgrims bathe", "Kashi Vishwanath Temple"], insiderTip: "Book a rowing boat (not motorboat) at dawn from Assi Ghat — you glide silently past waking ghats as morning light hits the river and pilgrims bathe, long before the day's crowds begin." },
