  "vienna": { scores: { beaches: 2, nightlife: 6, food: 8, activities: 10, family: 8, value: 5 }, tags: ["city-break", "culture"], foodPerDay: "$33–48", hotelPerNight: "$95–124", dishes: ["Wiener Schnitzel at Figlmüller", "Sachertorte at Café Sacher", "Tafelspitz"], sights: ["Schönbrunn Palace", "Kunsthistorisches Museum (KHM)", "Stephansdom"], insiderTip: "Buy a Stehplatz standing ticket to the State Opera for 3–4 € — queue 80 minutes, tie your scarf around the railing to reserve your spot, and enjoy the world's finest opera for the price of a beer." },
