export function getFacts(slug: string): DestinationFacts | undefined {
  return DESTINATION_FACTS[slug];
}

/** Slugs carrying a given tag. */
export function slugsWithTag(tag: string): string[] {
  return Object.entries(DESTINATION_FACTS)
    .filter(([, f]) => f.tags?.includes(tag))
    .map(([slug]) => slug);
}
